def gen_insert(table, fields):
    return "INSERT INTO " + table + "(" + ", ".join(fields) + ") VALUES(" + ", ".join("?" for _ in fields) + ")"

def gen_select(table, pk):
    return "SELECT * FROM " + table + " WHERE " + pk + " = ?"

def gen_update(table, fields, pk):
    return "UPDATE " + table + " SET " + ", ".join(f + " = ?" for f in fields) + " WHERE " + pk + " = ?"

def gen_delete(table, pk):
    return "DELETE FROM " + table + " WHERE " + pk + " = ?"

fields = ["user_name", "age"]
print(gen_insert("t_user", fields))
print(gen_select("t_user", "id"))
print(gen_update("t_user", fields, "id"))
print(gen_delete("t_user", "id"))
